/// <summary>
/// Errors crossing the generated foreign-language boundary.
/// </summary>
public class BindingException: UniffiException {
    BindingException() : base() {}
    BindingException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    /// <summary>
    /// Endpoint, credential, or trust configuration was rejected by Rust.
    /// </summary>
    
    public class Configuration : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Configuration(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The Rust-owned transport could not be constructed or reached.
    /// </summary>
    
    public class Transport : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Transport(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The service rejected an operation.
    /// </summary>
    
    public class Service : BindingException {
        // Members
        public int @grpcCode;
        public int? @serviceCode;
        public string @detailMessage;

        // Constructor
        public Service(
                int @grpcCode, 
                int? @serviceCode, 
                string @detailMessage) : base(
                "@grpcCode" + "=" + @grpcCode+ ", " +
                "@serviceCode" + "=" + @serviceCode+ ", " +
                "@detailMessage" + "=" + @detailMessage) {

            this.@grpcCode = @grpcCode;

            this.@serviceCode = @serviceCode;

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// Rust's canonical request validator rejected an operation.
    /// </summary>
    
    public class Contract : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Contract(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// Rust could not project a wire value into its semantic domain.
    /// </summary>
    
    public class Semantic : BindingException {
        // Members
        public string @detailMessage;

        // Constructor
        public Semantic(
                string @detailMessage) : base(
                "@detailMessage" + "=" + @detailMessage) {

            this.@detailMessage = @detailMessage;
        }
    }
    
    /// <summary>
    /// The Rust-owned operation observed cancellation.
    /// </summary>
    public class Cancelled : BindingException {
        public Cancelled() : base() {}
    }
    
    

    
}

