    public override CancellationHandle? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterTypeCancellationHandle.INSTANCE.Read(stream);
    }

    public override int AllocationSize(CancellationHandle? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterTypeCancellationHandle.INSTANCE.AllocationSize((CancellationHandle)value);
        }
    }

    public override void Write(CancellationHandle? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterTypeCancellationHandle.INSTANCE.Write((CancellationHandle)value, stream);
        }
    }
}




